import React, { useEffect, useState } from "react";

function DisplayFoodTruck() {
  const [vendors, setVendors] = useState([]);

  useEffect(() => {
    // Mock Data (Replace with API call later)
    setVendors([
      { id: 1, name: "John’s Burgers", city: "Chennai", cuisine: "Burgers" },
      { id: 2, name: "Spice Hub", city: "Bangalore", cuisine: "Indian" },
    ]);
  }, []);

  return (
    <div className="min-h-screen bg-gray-50 p-8">
      <h2 className="text-3xl font-bold text-center text-purple-600 mb-8">
        🍴 Registered Food Trucks
      </h2>
      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
        {vendors.map((vendor) => (
          <div
            key={vendor.id}
            className="bg-white p-6 rounded-xl shadow-lg hover:shadow-2xl transition"
          >
            <h3 className="text-xl font-semibold text-gray-800">{vendor.name}</h3>
            <p className="text-gray-600">{vendor.city}</p>
            <span className="inline-block mt-2 bg-purple-100 text-purple-700 px-3 py-1 rounded-full text-sm">
              {vendor.cuisine}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

export default DisplayFoodTruck;
